<script setup>
import { ref } from 'vue'
import { FileCode2, UploadCloud } from 'lucide-vue-next'
import http from '../api/http'
const file=ref(null),busy=ref(false),error=ref(''),result=ref(null)
function select(event){file.value=event.target.files[0]}
async function scan(){if(!file.value)return;busy.value=true;error.value='';const body=new FormData();body.append('file',file.value);try{const r=await http.post('/scans/pom',body);result.value=r.data}catch(e){error.value=e.message||'扫描失败'}finally{busy.value=false}}
</script>
<template><div class="page scan"><p class="eyebrow">MAVEN DEPENDENCY SCAN</p><h1 class="page-title">依赖风险扫描</h1><div class="scan-grid"><section class="drop"><UploadCloud :size="42"/><h2>上传项目 pom.xml</h2><p>解析直接依赖，并与Spark生成的Java组件漏洞库匹配。文件不会执行。</p><label class="btn primary"><input type="file" accept=".xml" @change="select" hidden>选择文件</label><strong v-if="file"><FileCode2 :size="17"/>{{file.name}}</strong><button class="btn" :disabled="!file||busy" @click="scan">{{busy?'正在扫描…':'开始扫描'}}</button><p v-if="error" class="error">{{error}}</p></section><section class="result"><template v-if="result"><p class="eyebrow">SCAN RESULT</p><div class="score">{{result.riskDependencies}}<small>/ {{result.totalDependencies}}</small></div><h2>{{result.projectName}}</h2><p>最高严重度：<span class="status red">{{result.highestSeverity}}</span></p><table class="data-table"><thead><tr><th>组件</th><th>版本</th><th>漏洞</th></tr></thead><tbody><tr v-for="item in result.dependencies" :key="item.groupId+item.artifactId"><td>{{item.groupId}}:{{item.artifactId}}</td><td>{{item.version||'未声明'}}</td><td>{{item.vulnerabilityCount}}</td></tr></tbody></table></template><div v-else class="result-empty">扫描结果将在这里显示</div></section></div></div></template>
<style scoped>.scan-grid{display:grid;grid-template-columns:minmax(320px,.8fr) 1.2fr;border:1px solid #111;margin-top:42px;min-height:560px}.drop{padding:50px;border-right:1px solid #111;display:flex;flex-direction:column;align-items:flex-start;gap:18px}.drop>svg{color:var(--red)}.drop h2,.drop p{margin:0}.drop p{color:#666;line-height:1.6}.drop strong{display:flex;gap:8px;align-items:center}.result{padding:40px}.result-empty{height:100%;display:grid;place-items:center;color:#777}.score{font-size:90px;font-weight:700;letter-spacing:-.08em;color:var(--red)}.score small{font-size:24px;color:#777}.error{color:var(--red)}@media(max-width:850px){.scan-grid{grid-template-columns:1fr}.drop{border-right:0;border-bottom:1px solid #111}}</style>
